  var gm = String(P.gameMode.getGameModeForPlayer());
  AutoJS.write('astral_test_pickup_gm.txt', gm);
  Econ.setBalance(P, 0);
  AutoJS.command('gamemode survival @a');
  var out = { autoDeposit: SCC.isAutoDepositEnabled(), walletEnabled: SCC.isWalletEnabled(), storageAvailable: Econ.isAvailable(), balanceBefore: Econ.getBalance(P), carriedBefore: SCC.countCarriedValue(P), originalGameMode: gm, gameModeNow: String(P.gameMode.getGameModeForPlayer()) };
  AutoJS.command('execute at @a run summon minecraft:item ~ ~0.5 ~ {Item:{id:"astral_dice:star_coin",count:3}}');
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var Econ = Java.loadClass('com.merlinkitsune.starengine.economy.StarEngineEconomy');
