})()

(function(){
  var P = AutoJS.players()[0];
  var Econ = Java.loadClass('com.merlinkitsune.starengine.economy.StarEngineEconomy');
  var SCC = Java.loadClass('com.merlinkitsune.astral_dice.economy.StarCoinCurrency');
  var out = {};
  out.balanceAfter = Econ.getBalance(P);
  out.balanceDelta = out.balanceAfter - 0;
  out.carriedAfter = SCC.countCarriedValue(P);
  out.totalGained = out.balanceDelta + out.carriedAfter;
  var it = AutoJS.level().getAllEntities().iterator();
  var coins = 0, items = 0;
  while (it.hasNext()) {
    var e = it.next();
    if (!(e instanceof Java.loadClass('net.minecraft.world.entity.item.ItemEntity'))) continue;
    items++;
    var st = e.getItem();
    if (String(st.getItem()) !== 'star_coin') continue;
    coins += st.getCount();
  }
  out.looseCoinItems = coins;
  out.looseItemEntities = items;
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var Econ = Java.loadClass('com.merlinkitsune.starengine.economy.StarEngineEconomy');
  var SCC = Java.loadClass('com.merlinkitsune.astral_dice.economy.StarCoinCurrency');
  var want = Number(AutoJS.read('astral_test_pickup.txt'));
  Econ.setBalance(P, want);
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  var out = {};
  out.balanceRestored = (Econ.getBalance(P) === want);
  out.carriedFinal = SCC.countCarriedValue(P);
  return out;
})()
